{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "CC-292, a covalent BTK inhibitor sharing the acrylamide and aminopyrimidine/aniline core with the query, showed excellent oral bioavailability in humans, providing the most transferable supportive evidence for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Rilzabrutinib, another covalent BTK inhibitor, had absolute oral bioavailability below 5% in healthy participants; this is contradictory, but its bulkier pyrazolopyrimidine scaffold and different warhead/linker reduce transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Entrectinib, a kinase inhibitor with oral bioavailability >50% in humans, supports high F, though structural similarity to the query is limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Flupirtine had an absolute oral bioavailability of 90.0% in healthy young volunteers, supporting high F, though it is structurally unrelated.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Sunitinib had an absolute oral bioavailability of about 50% in humans, supporting high F, though structural similarity is low.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a covalent BTK inhibitor with an acrylamide warhead and aminopyrimidine core. The closest relevant analogue, CC-292, showed excellent human oral bioavailability, and multiple other drugs with oral F >50% support high bioavailability. The low-F rilzabrutinib record is outweighed by structural differences and the preponderance of high-F evidence, so the query is predicted high (F >= 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present in the provided evidence.",
    "All retrieved analogues have low Morgan similarity (0.21-0.23), limiting quantitative transfer.",
    "Rilzabrutinib shows that covalent BTK inhibitors are not uniformly high-F, so query-specific PK data would reduce residual uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

